[CmdletBinding()] param([Parameter(Mandatory)][string]$ResourceGroup,[Parameter(Mandatory)][string]$OutputDirectory,[Parameter(Mandatory)][string]$Subscription,[Parameter(Mandatory)][string]$ResourceIdsFile)
. (Join-Path $PSScriptRoot 'Common-AzureCollector.ps1');$doc=New-CollectorDocument 'Microsoft.Security/subscriptionPosture' 'DefenderForCloud' $ResourceGroup $Subscription
$resourceIds=@(Get-Content -Raw $ResourceIdsFile | ConvertFrom-Json)
function Select-WorkloadFindings($result){if($result.success -and $result.data){$result.data=@($result.data|Where-Object{$finding=$_|ConvertTo-Json -Depth 100 -Compress;@($resourceIds|Where-Object{$finding.IndexOf($_,[System.StringComparison]::OrdinalIgnoreCase)-ge 0}).Count -gt 0})};return $result}
Add-CollectorSection $doc 'pricing' (Invoke-AzCommandJson 'security.pricing.list' @('security','pricing','list') $Subscription);Add-CollectorSection $doc 'contacts' (Invoke-AzCommandJson 'security.contact.list' @('security','contact','list') $Subscription);Add-CollectorSection $doc 'assessments' (Select-WorkloadFindings (Invoke-AzCommandJson 'security.assessment.list' @('security','assessment','list') $Subscription));Add-CollectorSection $doc 'recommendations' (Select-WorkloadFindings (Invoke-AzCommandJson 'advisor.recommendation.list.security' @('advisor','recommendation','list','--category','Security','--resource-group',$ResourceGroup) $Subscription))
$file=Join-Path $OutputDirectory 'defender-for-cloud.json';Save-CollectorDocument $doc $file;[pscustomobject]@{resourceType='defenderForCloud';name='subscriptionPosture';outputFile=$file}